package kv_test

import (
	"os"
	"testing"
	"time"

	"github.com/ai-verification/kv-store/kv"
)

func TestSetGet(t *testing.T) {
	s := kv.New()
	s.Set("k", "v", 0)
	val, ok := s.Get("k")
	if !ok || val != "v" {
		t.Fatalf("expected (v, true), got (%s, %v)", val, ok)
	}
}

func TestGetMissing(t *testing.T) {
	s := kv.New()
	_, ok := s.Get("missing")
	if ok {
		t.Fatal("expected false")
	}
}

func TestDelete(t *testing.T) {
	s := kv.New()
	s.Set("k", "v", 0)
	if !s.Delete("k") {
		t.Fatal("expected true")
	}
	_, ok := s.Get("k")
	if ok {
		t.Fatal("expected key gone")
	}
}

func TestList(t *testing.T) {
	s := kv.New()
	s.Set("a", "1", 0)
	s.Set("b", "2", 0)
	keys := s.List()
	if len(keys) != 2 {
		t.Fatalf("expected 2 keys, got %d", len(keys))
	}
}

func TestTTLExpiry(t *testing.T) {
	s := kv.New()
	s.Set("temp", "val", 20*time.Millisecond)
	time.Sleep(30 * time.Millisecond)
	_, ok := s.Get("temp")
	if ok {
		t.Fatal("expected key to be expired")
	}
}

func TestSnapshot(t *testing.T) {
	s := kv.New()
	s.Set("x", "1", 0)
	s.Set("y", "2", 0)
	tmp, _ := os.CreateTemp("", "snapshot*.json")
	tmp.Close()
	defer os.Remove(tmp.Name())
	if err := s.Snapshot(tmp.Name()); err != nil {
		t.Fatal(err)
	}
	s2 := kv.New()
	if err := s2.LoadSnapshot(tmp.Name()); err != nil {
		t.Fatal(err)
	}
	val, ok := s2.Get("x")
	if !ok || val != "1" {
		t.Fatalf("expected x=1, got %s %v", val, ok)
	}
}
